-- Removes the 000017 entries. Refused while any bundle still names one:
-- deleting a registered action under a live grant would leave a bundle
-- holding a name the registry no longer recognises.
DO $$
DECLARE
    v_used TEXT;
BEGIN
    SELECT string_agg(DISTINCT a, ', ') INTO v_used
      FROM permission_bundle_defs b, unnest(b.permitted_actions) a
     WHERE a = ANY (ARRAY['APPROVE_VARIANCE', 'CLAUSE_ACTIVATE', 'CLAUSE_APPROVE', 'CLAUSE_RETIRE', 'CLAUSE_SUBMIT_LEGAL_REVIEW', 'CLAUSE_SUPERSEDE', 'CONTRACT_APPROVE', 'CONTRACT_RECORD_EXECUTION', 'CONTRACT_RENEW', 'CONTRACT_SEND_FOR_SIGNATURE', 'CONTRACT_SUBMIT_REVIEW', 'CURRENCY_ACTIVATE', 'CURRENCY_IMPORT', 'CURRENCY_RESTRICT', 'CURRENCY_RETIRE', 'CURRENCY_TENANT_DISABLE', 'CURRENCY_TENANT_ENABLE', 'DEVIATION_RULE_APPROVE', 'DEVIATION_RULE_CREATE', 'EXPORT_PACKAGE_MANAGE', 'EXPORT_PACKAGE_READ', 'FISCAL_CALENDAR_ACTIVATE', 'FISCAL_CALENDAR_APPROVE', 'FISCAL_CALENDAR_PROPOSE', 'FIXITY_MANAGE', 'FIXITY_READ', 'GL_SOFT_CLOSE_POSTING_OVERRIDE', 'IDENTITY_SUPPORT_CONTEXT_APPROVE', 'INVOICE_MATCH_EXCEPTION_RESOLVE', 'INVOICE_MATCH_READ', 'INVOICE_MATCH_RUN', 'MATCH_POLICY_MANAGE', 'OBLIGATION_COMPLETE', 'OBLIGATION_DISPUTE', 'OBLIGATION_MARK_DUE', 'OBLIGATION_MARK_IN_PROGRESS', 'OBLIGATION_RECORD_BREACH', 'OBLIGATION_SCHEDULE', 'OBLIGATION_SUPERSEDE', 'OBLIGATION_VALIDATE', 'OBLIGATION_WAIVE', 'PERIOD_CLOSE_APPROVE', 'PERIOD_CLOSE_EXCLUSION_APPROVE', 'PERIOD_MATERIALIZE', 'PERIOD_REOPEN_APPROVE', 'PERIOD_STATE_COMMAND', 'PO_APPROVE', 'PO_APPROVE_HIGHVALUE', 'PO_CANCEL', 'PO_CREATE', 'PO_HOLD', 'PO_PROGRESS_RECORD', 'PO_SUBMIT', 'PO_SUPPLIER_EXCEPTION', 'PROJECT_MILESTONE_APPROVE', 'PROJECT_MILESTONE_MANAGE', 'PR_REQUEST_CANCEL', 'PR_REQUEST_CONVERT', 'PR_REQUEST_MANAGE', 'PR_REQUEST_READ', 'PR_REQUEST_SUBMIT', 'REDACTION_MANAGE', 'REDACTION_READ', 'RENDITION_MANAGE', 'RENDITION_READ', 'RESOLUTION_CLOSE_VOTING', 'RESOLUTION_OPEN_VOTING', 'RESOLUTION_SUPERSEDE']);
    IF v_used IS NOT NULL THEN
        RAISE EXCEPTION '000017 down refused: still granted by a bundle: %', v_used;
    END IF;
END
$$;

DELETE FROM permission_definitions
 WHERE naming = 'LEGACY'
   AND description LIKE 'Enforced by %'
   AND action_name = ANY (ARRAY['APPROVE_VARIANCE', 'CLAUSE_ACTIVATE', 'CLAUSE_APPROVE', 'CLAUSE_RETIRE', 'CLAUSE_SUBMIT_LEGAL_REVIEW', 'CLAUSE_SUPERSEDE', 'CONTRACT_APPROVE', 'CONTRACT_RECORD_EXECUTION', 'CONTRACT_RENEW', 'CONTRACT_SEND_FOR_SIGNATURE', 'CONTRACT_SUBMIT_REVIEW', 'CURRENCY_ACTIVATE', 'CURRENCY_IMPORT', 'CURRENCY_RESTRICT', 'CURRENCY_RETIRE', 'CURRENCY_TENANT_DISABLE', 'CURRENCY_TENANT_ENABLE', 'DEVIATION_RULE_APPROVE', 'DEVIATION_RULE_CREATE', 'EXPORT_PACKAGE_MANAGE', 'EXPORT_PACKAGE_READ', 'FISCAL_CALENDAR_ACTIVATE', 'FISCAL_CALENDAR_APPROVE', 'FISCAL_CALENDAR_PROPOSE', 'FIXITY_MANAGE', 'FIXITY_READ', 'GL_SOFT_CLOSE_POSTING_OVERRIDE', 'IDENTITY_SUPPORT_CONTEXT_APPROVE', 'INVOICE_MATCH_EXCEPTION_RESOLVE', 'INVOICE_MATCH_READ', 'INVOICE_MATCH_RUN', 'MATCH_POLICY_MANAGE', 'OBLIGATION_COMPLETE', 'OBLIGATION_DISPUTE', 'OBLIGATION_MARK_DUE', 'OBLIGATION_MARK_IN_PROGRESS', 'OBLIGATION_RECORD_BREACH', 'OBLIGATION_SCHEDULE', 'OBLIGATION_SUPERSEDE', 'OBLIGATION_VALIDATE', 'OBLIGATION_WAIVE', 'PERIOD_CLOSE_APPROVE', 'PERIOD_CLOSE_EXCLUSION_APPROVE', 'PERIOD_MATERIALIZE', 'PERIOD_REOPEN_APPROVE', 'PERIOD_STATE_COMMAND', 'PO_APPROVE', 'PO_APPROVE_HIGHVALUE', 'PO_CANCEL', 'PO_CREATE', 'PO_HOLD', 'PO_PROGRESS_RECORD', 'PO_SUBMIT', 'PO_SUPPLIER_EXCEPTION', 'PROJECT_MILESTONE_APPROVE', 'PROJECT_MILESTONE_MANAGE', 'PR_REQUEST_CANCEL', 'PR_REQUEST_CONVERT', 'PR_REQUEST_MANAGE', 'PR_REQUEST_READ', 'PR_REQUEST_SUBMIT', 'REDACTION_MANAGE', 'REDACTION_READ', 'RENDITION_MANAGE', 'RENDITION_READ', 'RESOLUTION_CLOSE_VOTING', 'RESOLUTION_OPEN_VOTING', 'RESOLUTION_SUPERSEDE']);
